changeSet.sql:
IF (NOT EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = 'Intersect' AND COLUMN_NAME = 'uid'))
BEGIN
	ALTER TABLE [dbo].[Intersect] ADD [uid] uniqueidentifier constraint DF_Intersect_uid default(newid()) NOT NULL;
	CREATE NONCLUSTERED INDEX IX_Intersect_Uid ON [dbo].[Intersect] ( [Uid] ASC );
END

changeSet.rollback:
IF (EXISTS (SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'dbo' AND TABLE_NAME = 'Intersect' AND COLUMN_NAME = 'uid'))
BEGIN
    ALTER TABLE [dbo].[Intersect] DROP CONSTRAINT [DF_Intersect_uid];
	ALTER TABLE [dbo].[Intersect] DROP COLUMN [uid];
END
